CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE data_versions (id bigserial PRIMARY KEY, source varchar(50) NOT NULL, period varchar(20), status varchar(20) NOT NULL CHECK(status IN ('LOADING','READY','ACTIVE','FAILED')), row_count bigint, created_at timestamptz NOT NULL DEFAULT now(), activated_at timestamptz);
CREATE UNIQUE INDEX data_versions_one_active ON data_versions(source) WHERE status='ACTIVE';
CREATE TABLE ingest_runs (id bigserial PRIMARY KEY, source varchar(50) NOT NULL, target_period varchar(20), status varchar(20) NOT NULL CHECK(status IN ('RUNNING','SUCCEEDED','FAILED')), fetched int NOT NULL DEFAULT 0, inserted int NOT NULL DEFAULT 0, updated int NOT NULL DEFAULT 0, failed int NOT NULL DEFAULT 0, error_message text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE INDEX ingest_runs_source_started ON ingest_runs(source,started_at DESC);
CREATE UNIQUE INDEX ingest_runs_one_running ON ingest_runs(source) WHERE status='RUNNING';
CREATE TABLE raw_payloads (id bigserial PRIMARY KEY, run_id bigint NOT NULL REFERENCES ingest_runs(id), source varchar(50) NOT NULL, request_key varchar(500) NOT NULL, payload jsonb NOT NULL, checksum char(64) NOT NULL, fetched_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,request_key));